      "Därifrån går rutten söderut genom Serengetis fast bosatta vilt — lejonflockar, leoparder i flodträden, geparder med ungar på det öppna gräset — innan två hela nätter i Ngorongorokratern, som avslutas med ett genuint besök hos ett massajsamhälle och ett stopp i Mto wa Mbu på vägen tillbaka till Arusha. Finns i tre nivåer — Wilderness Trail, Wilderness Reserve och Wilderness Sovereign — som följer exakt samma åtta dagar långa rutt, med nivån på läger och lodge som förändras under dig.",
